/**
 * Locale es para bootstrap-datepicker.
 *
 * El template NexaDash trae la librería pero NO su carpeta `locales/`, así que el calendario
 * salía en inglés ("August 2026", "Mo Tu We…") aunque el campo mostrara dd/mm/aaaa. Sin este
 * archivo, `language: 'es'` cae en silencio al diccionario `en` — por eso antes ni se declaraba.
 *
 * `weekStart: 1` (lunes) es la convención argentina, y coincide con el default que ya usaba
 * `fecha-ar.js` antes de que existiera este locale.
 */
;(function ($) {
    $.fn.datepicker.dates.es = {
        days: ['Domingo', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado'],
        daysShort: ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'],
        daysMin: ['Do', 'Lu', 'Ma', 'Mi', 'Ju', 'Vi', 'Sá'],
        months: ['Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio', 'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'],
        monthsShort: ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'],
        today: 'Hoy',
        clear: 'Borrar',
        format: 'dd/mm/yyyy',
        weekStart: 1,
        monthsTitle: 'Meses',
    };
}(jQuery));
